import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"心跳与超时","description":"","frontmatter":{"title":"心跳与超时","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heartbeat-timeout.md","filePath":"cs/heartbeat-timeout.md","lastUpdated":1789023840000}'),T={name:"cs/heartbeat-timeout.md"};function c(m,a,_,u,E,f){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="心跳与超时" tabindex="-1">心跳与超时 <a class="header-anchor" href="#心跳与超时" aria-label="Permalink to &quot;心跳与超时&quot;">​</a></h1><div class="epigraph"><p>空闲连接与半开要用主动心跳在应用层刷新；超时值要大于 RTT 与短暂拥塞，小于用户可忍受的失败检测。</p><footer>—— 据 RFC 1122 对照；gRPC keepalive；WebSocket ping 整理</footer></div><p><a href="/cs/keepalive-half-open">TCP keepalive</a> 太慢。<a href="/cs/message-framing">成帧</a> 已能发小消息。<a href="/cs/message-framing">上一课</a> 留下存活检测。缺口是<strong>应用心跳</strong>：间隔、超时、与 RTO 叠。本课不把重试写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>反向代理、NAT、Maglev 都可能静默丢空闲。应用 ping/pong：间隔 15–60 s 常见，远短于 TCP keepalive。超时：连续未应答则拆，触发发现换后端。与 NTP 无关。无线调度抖动要给余量，否则假死。SSE 用注释行当心跳。QUIC PING 帧。过频心跳在万连接上成 C10K 负载。</p><p>不要把心跳当业务数据。</p><p><span class="marginnote">间隔无唯一 RFC。本课钉原则。</span></p><h3 id="值在-rtt-与-nat-之间" tabindex="-1">值在 RTT 与 NAT 之间 <a class="header-anchor" href="#值在-rtt-与-nat-之间" aria-label="Permalink to &quot;值在 RTT 与 NAT 之间&quot;">​</a></h3><p>太短杀卫星会话，太长留半开。心跳也是 C10K 负载。三层心跳要错开防同步。不是业务数据。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：传输 keepalive / 应用心跳 / LB 健康检查。画：定时发 → 等 pong → 失败则关。与 ICE 刷新一致。</p>',11)),(e(),n(h,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TMR%5B%22%E5%AE%9A%E6%97%B6%22%5D%20--%3E%20PING%5B%22%E5%BF%83%E8%B7%B3%E5%B8%A7%22%5D%0A%20%20PING%20--%3E%20PONG%5B%22%E5%BA%94%E7%AD%94%22%5D%0A%20%20FAIL%5B%22%E8%B6%85%E6%97%B6%22%5D%20--%3E%20CLOSE%5B%22%E6%8B%86%E8%BF%9E%E6%8E%A5%E5%B9%B6%E5%8F%91%E7%8E%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>超时 \\(\\lt\\) 2×RTT 会在卫星上误杀。超时 &gt;&gt; NAT 会话则半开。与 ABR 无关。服务发现心跳是控制面，连接心跳是数据面会话。</p><p>安全：无认证的心跳可被用来保活攻击连接表，要绑会话。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入指数退避的全部（下一课重试）。重试与幂等是下一课。后课默认：应用心跳检测会话死活；值按 RTT 与 NAT 定。</p><p>三层心跳（TCP、HTTP、业务）要错开，避免同步风暴。</p><p>上一课留下的缺口在本课收口；「心跳与超时」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/retry-idempotency">重试与幂等</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>应用心跳补 NAT 与代理空闲策略。</li><li>超时在 RTT 与用户等待之间。</li><li>规模上心跳也是负载。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 1122 对照；应用实践。</li></ul>',10))])}const P=o(T,[["render",c]]);export{B as __pageData,P as default};
